#!/usr/bin/env python3
import csv, math, os, collections
R=os.path.expanduser("~/workspace/jverifydestroy/experiments/results")
def wilson(k,n,z=1.959964):
    if n==0: return (0,0)
    p=k/n; d=1+z*z/n; c=p+z*z/(2*n); m=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))
    return ((c-m)/d,(c+m)/d)
rows=list(csv.DictReader(open(R+"/memory_trials.csv")))
agg=collections.defaultdict(lambda:[0,0])
for r in rows: agg[(r['gc'],r['method'],r['jit'])][0]+=int(r['found']); agg[(r['gc'],r['method'],r['jit'])][1]+=1
order_gc=["UseSerialGC","UseParallelGC","UseG1GC","UseZGC","UseShenandoahGC"]
def pct(k,n): return f"{100*k/n:.1f}%"
lines=[]
lines.append("# RESULTS — generated only from real runs\n")
lines.append("Environment: Temurin OpenJDK 25.0.5+8 LTS, Linux 7.0 x86_64, victim heap `-Xmx64m`, 32-byte canaries, parent process scans child JVM `/proc/<pid>/mem` (anonymous + `/memfd:` regions; library mappings skipped). Generated by `experiments/make_results.py` from the CSVs in `experiments/results/`. **Logical-level only — physical media is never verified.**\n")
lines.append("## Memory: false-assurance rate by GC × method (tiered JIT)\n")
lines.append("False assurance = the method claims success (wipe methods always do) ∧ the validator finds the canary immediately after destruction. Each trial's secret survived one promotion GC under churn *before* the method ran — the realistic case of a secret that has lived in the heap. `drop` is the no-wipe baseline (its found rate is also the validator's sensitivity).\n")
lines.append("| GC | drop (baseline) | fill (Arrays.fill) | multipass (7×) | fill + 2×GC after |")
lines.append("|---|---|---|---|---|")
for gc in order_gc:
    cells=[]
    for m in ["drop","fill","multipass","fillgc"]:
        k,n=agg[(gc,m,"tiered")]; lo,hi=wilson(k,n); cells.append(f"{k}/{n} = {pct(k,n)} [{100*lo:.1f}–{100*hi:.1f}]")
    lines.append(f"| {gc.replace('Use','').replace('GC','')} | "+" | ".join(cells)+" |")
lines.append("\n## Memory: fill under the interpreter (`-Xint`) vs tiered\n")
lines.append("| GC | tiered | -Xint |")
lines.append("|---|---|---|")
for gc in order_gc:
    k1,n1=agg[(gc,"fill","tiered")]; k2,n2=agg[(gc,"fill","-Xint")]
    lines.append(f"| {gc.replace('Use','').replace('GC','')} | {k1}/{n1} = {pct(k1,n1)} | {k2}/{n2} = {pct(k2,n2)} |")
lines.append("\n**Reading the matrix.** (1) Validator sensitivity is 100% (200/200) in every `drop` cell: when a secret is not wiped, the scanner finds it — the negative results below are not scanner blindness. (2) After a single promotion GC, wiping the live array leaves a findable stale copy in ~99–100% of trials on Serial, Parallel, G1 and ZGC — extra passes change nothing (multipass ≈ fill everywhere), and JIT mode changes nothing (the residue is a GC copy, not a JIT artefact — consistent with spike H1 finding no dead-store elimination). (3) Shenandoah is the outlier: 2/200 (1.0%) across all wipe methods. (4) ZGC `fillgc` drops to 99/200 (49.5%): forcing two more GCs after wiping halves ZGC residue but leaves half. (5) No memory wipe cell measured 0, so no rule-of-three bound is needed here; Shenandoah's 2/200 is reported as measured, not rounded to zero.\n")
frows=list(csv.DictReader(open(R+"/file_trials.csv")))
lines.append("## Files (N=200 per method)\n")
lines.append("| Method | Medium | Found | Note |")
lines.append("|---|---|---|---|")
for r in frows:
    lines.append(f"| {r['method']} | {r['medium']} | {r['found']}/{r['n']} | {r['note']} |")
lines.append("\nDelete-only leaves everything (200/200 in the raw ext4 image). Overwrite reads back clean at the **logical** level in 200/200 for both 1-pass and 7-pass — i.e. extra passes buy nothing measurable at logical level, and COW/physical copies remain NOT_CHECKABLE (spike H6).\n")
trows=list(csv.DictReader(open(R+"/tamper_trials.csv")))
lines.append("## Log tamper detection (jvd-verify, N=50 per type)\n")
lines.append("| Tamper | Detected |")
lines.append("|---|---|")
for r in trows: lines.append(f"| {r['tamper_type']} | {r['detected']}/{r['n']} |")
lines.append("\nMethod note (kept honest): leaves are stored Base64-encoded; the first backdate batch silently failed to modify anything (a regex aimed at raw JSON) and detected 0/50 *because nothing had been tampered*. The tamper was fixed to decode/modify/re-encode and rerun: 50/50. The verifier was right both times.\n")
orows=list(csv.DictReader(open(R+"/overhead.csv")))
lines.append("## Overhead (median of 20 runs, includes JVM startup of the CLI process)\n")
lines.append("| Operation | Median |")
lines.append("|---|---|")
for r in orows: lines.append(f"| {r['operation']} (full txn: vault+scrub+commit+evidence+log) | {r['median_ms']} ms |")
lines.append("\n## Experiment incidents (all caught by controls, all disclosed)")
lines.append("1. Victim v1 held the raw pattern in `main`'s frame — every cell read 200/200 including wiped ones. Caught because Serial/fill at 200/200 was implausible; fixed by generating the pattern inside the trial frame.")
lines.append("2. Victim v2 cloned the pattern and wiped only the clone — same symptom, same catch. Fixed: the secret *is* the pattern; only its hex encoding leaves the frame.")
lines.append("3. ZGC maps its heap via `/memfd:java_heap`; a scanner skipping all file-backed mappings finds nothing under ZGC, including unwiped controls (drop read 0/20 in smoke). Fixed by including `/memfd:` regions. **The same skip rule exists in the shipped `verify` module's ProcScanner** — there, the positive control fails too, so runs report INVALID rather than a false NOT_FOUND (the control design working as intended), but ZGC targets deserve a scanner fix; logged as a known issue, not silently patched after the fact.")
lines.append("4. Backdate batch 1 no-op (above).")
open(os.path.expanduser("~/workspace/jverifydestroy/docs/RESULTS.md"),"w").write("\n".join(lines)+"\n")
print("RESULTS.md written")
